// Generated by Cube Creator. Builds Unity ParticleSystems from exported layers.
// Sprites are loaded from Resources/CubeCreatorSprites/<sprite>.png.
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Rendering;

namespace CubeCreator
{
    public static class CubeCreatorParticles
    {
        static readonly Dictionary<string, Texture2D> SpriteCache = new Dictionary<string, Texture2D>();

        public static ParticleSystem Build(ParticleLayer p, Transform parent, Vector3 half, bool burstOnly)
        {
            var go = new GameObject((burstOnly ? "ClickBurst_" : "Particles_") + p.name);
            go.transform.SetParent(parent, false);
            var ps = go.AddComponent<ParticleSystem>();
            ps.Stop(true, ParticleSystemStopBehavior.StopEmittingAndClear);

            float speedMin = p.speed * (1f - p.speedVar);
            float speedMax = p.speed;

            var main = ps.main;
            main.loop = true;
            main.playOnAwake = true;
            main.duration = 5f;
            main.startLifetime = new ParticleSystem.MinMaxCurve(Mathf.Max(0.05f, p.lifetime * (1f - p.lifetimeVar)), p.lifetime);
            main.startSize = new ParticleSystem.MinMaxCurve(p.size * 0.6f, p.size * 1.4f);
            main.gravityModifier = p.gravity / 9.81f;
            main.simulationSpace = ParticleSystemSimulationSpace.Local;
            main.scalingMode = ParticleSystemScalingMode.Hierarchy;
            main.maxParticles = burstOnly ? 1000 : Mathf.Clamp(Mathf.CeilToInt(p.rate * p.lifetime * 1.3f) + 64, 64, 10000);

            if (p.colorMode == "randomHue")
            {
                var rainbow = new Gradient();
                rainbow.SetKeys(
                    new[] { new GradientColorKey(Color.red, 0f), new GradientColorKey(Color.yellow, 0.2f), new GradientColorKey(Color.green, 0.4f), new GradientColorKey(Color.cyan, 0.6f), new GradientColorKey(Color.blue, 0.8f), new GradientColorKey(Color.magenta, 1f) },
                    new[] { new GradientAlphaKey(1f, 0f), new GradientAlphaKey(1f, 1f) });
                main.startColor = new ParticleSystem.MinMaxGradient(rainbow) { mode = ParticleSystemGradientMode.RandomColor };
            }
            else main.startColor = Color.white;

            var emission = ps.emission;
            emission.rateOverTime = burstOnly ? 0f : p.rate;

            ConfigureShape(ps, p, half, speedMin, speedMax);

            if (p.drag > 0f)
            {
                var limit = ps.limitVelocityOverLifetime;
                limit.enabled = true;
                limit.limit = 1000f;
                limit.drag = p.drag;
            }

            if (p.turbulence > 0f)
            {
                var noise = ps.noise;
                noise.enabled = true;
                noise.strength = p.turbulence * 0.25f;
                noise.frequency = 1.5f;
                noise.scrollSpeed = 0.5f;
            }

            var col = ps.colorOverLifetime;
            col.enabled = true;
            Color c0 = ColorUtil.Parse(p.colorStart, Color.white);
            Color c1 = ColorUtil.Parse(p.colorEnd, Color.white);
            if (p.colorMode == "randomHue") c0 = c1 = Color.white;
            var grad = new Gradient();
            float fade = Mathf.Clamp(p.fadeIn, 0f, 0.5f);
            grad.SetKeys(
                new[] { new GradientColorKey(c0, 0f), new GradientColorKey(c1, 1f) },
                fade > 0.001f
                    ? new[] { new GradientAlphaKey(0f, 0f), new GradientAlphaKey(p.opacity, fade), new GradientAlphaKey(p.opacity, 0.65f), new GradientAlphaKey(0f, 1f) }
                    : new[] { new GradientAlphaKey(p.opacity, 0f), new GradientAlphaKey(p.opacity, 0.65f), new GradientAlphaKey(0f, 1f) });
            col.color = new ParticleSystem.MinMaxGradient(grad);

            var sol = ps.sizeOverLifetime;
            sol.enabled = true;
            float end = Mathf.Max(0f, p.sizeEnd);
            float mult = Mathf.Max(1f, end);
            sol.size = new ParticleSystem.MinMaxCurve(mult, new AnimationCurve(new Keyframe(0f, 1f / mult), new Keyframe(1f, end / mult)));

            var renderer = go.GetComponent<ParticleSystemRenderer>();
            renderer.renderMode = p.sprite == "streak" ? ParticleSystemRenderMode.Stretch : ParticleSystemRenderMode.Billboard;
            if (p.sprite == "streak") { renderer.lengthScale = 2f; renderer.velocityScale = 0.15f; }
            renderer.material = MakeMaterial(p);

            ps.Play();
            return ps;
        }

        static void ConfigureShape(ParticleSystem ps, ParticleLayer p, Vector3 half, float speedMin, float speedMax)
        {
            var shape = ps.shape;
            shape.enabled = true;
            Vector3 b = half * p.emitScale;
            float maxB = Mathf.Max(b.x, Mathf.Max(b.y, b.z));
            switch (p.emitFrom)
            {
                case "volume": shape.shapeType = ParticleSystemShapeType.Box; shape.scale = b * 2f; shape.boxThickness = Vector3.one; break;
                case "top": shape.shapeType = ParticleSystemShapeType.Box; shape.scale = new Vector3(b.x * 2f, 0.001f, b.z * 2f); shape.position = new Vector3(0f, b.y, 0f); break;
                case "bottom": shape.shapeType = ParticleSystemShapeType.Box; shape.scale = new Vector3(b.x * 2f, 0.001f, b.z * 2f); shape.position = new Vector3(0f, -b.y, 0f); break;
                case "sphere": shape.shapeType = ParticleSystemShapeType.Sphere; shape.radius = maxB * 1.25f; shape.radiusThickness = 0f; break;
                case "ring": shape.shapeType = ParticleSystemShapeType.Circle; shape.radius = maxB * 1.4f; shape.radiusThickness = 0f; shape.rotation = new Vector3(-90f, 0f, 0f); break;
                case "point": shape.shapeType = ParticleSystemShapeType.Sphere; shape.radius = 0.001f; break;
                case "above": shape.shapeType = ParticleSystemShapeType.Box; shape.scale = new Vector3(b.x * 4f, 0.001f, b.z * 4f); shape.position = new Vector3(0f, b.y * 3.5f, 0f); break;
                default: shape.shapeType = ParticleSystemShapeType.Box; shape.scale = b * 2f; shape.boxThickness = Vector3.zero; break; // surface shell
            }

            var main = ps.main;
            var vel = ps.velocityOverLifetime;
            float spreadV = p.spread * Mathf.Max(0.05f, p.speed);
            switch (p.direction)
            {
                case "outward":
                    main.startSpeed = new ParticleSystem.MinMaxCurve(speedMin, speedMax);
                    shape.sphericalDirectionAmount = 1f;
                    shape.randomDirectionAmount = Mathf.Clamp01(p.spread);
                    break;
                case "inward":
                    main.startSpeed = new ParticleSystem.MinMaxCurve(-speedMax, -speedMin);
                    shape.sphericalDirectionAmount = 1f;
                    break;
                case "random":
                    main.startSpeed = new ParticleSystem.MinMaxCurve(speedMin, speedMax);
                    shape.randomDirectionAmount = 1f;
                    break;
                default:
                {
                    // up / down / orbit / swirlUp: drive with velocity over lifetime
                    main.startSpeed = 0f;
                    vel.enabled = true;
                    vel.space = ParticleSystemSimulationSpace.Local;
                    float ySign = p.direction == "down" ? -1f : 1f;
                    float yMin = 0f, yMax = 0f;
                    if (p.direction == "up" || p.direction == "down") { yMin = speedMin * ySign; yMax = speedMax * ySign; }
                    if (p.direction == "swirlUp") { yMin = speedMin * 0.7f; yMax = speedMax * 0.7f; }
                    vel.x = new ParticleSystem.MinMaxCurve(-spreadV, spreadV);
                    vel.y = new ParticleSystem.MinMaxCurve(Mathf.Min(yMin, yMax), Mathf.Max(yMin, yMax));
                    vel.z = new ParticleSystem.MinMaxCurve(-spreadV, spreadV);
                    float orbit = (p.direction == "orbit" || p.direction == "swirlUp") ? p.speed * 1.2f : 0f;
                    vel.orbitalX = new ParticleSystem.MinMaxCurve(0f, 0f);
                    vel.orbitalY = new ParticleSystem.MinMaxCurve(orbit, orbit);
                    vel.orbitalZ = new ParticleSystem.MinMaxCurve(0f, 0f);
                    break;
                }
            }
        }

        static Material MakeMaterial(ParticleLayer p)
        {
            bool additive = p.blending != "normal";
            Texture2D tex = LoadSprite(p.sprite);
            Color tint = Color.white * Mathf.Max(0.1f, p.brightness);
            tint.a = 1f;

            Shader urp = Shader.Find("Universal Render Pipeline/Particles/Unlit");
            if (urp != null)
            {
                var m = new Material(urp);
                m.SetFloat("_Surface", 1f);
                m.SetFloat("_Blend", additive ? 2f : 0f);
                m.SetFloat("_SrcBlend", (float)BlendMode.SrcAlpha);
                m.SetFloat("_DstBlend", additive ? (float)BlendMode.One : (float)BlendMode.OneMinusSrcAlpha);
                m.SetFloat("_ZWrite", 0f);
                m.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");
                m.renderQueue = (int)RenderQueue.Transparent;
                m.SetTexture("_BaseMap", tex);
                m.SetColor("_BaseColor", tint);
                return m;
            }
            Shader legacy = Shader.Find(additive ? "Legacy Shaders/Particles/Additive" : "Legacy Shaders/Particles/Alpha Blended");
            if (legacy != null)
            {
                var m = new Material(legacy);
                m.SetTexture("_MainTex", tex);
                m.SetColor("_TintColor", new Color(0.5f, 0.5f, 0.5f, 0.5f) * Mathf.Min(2f, p.brightness));
                return m;
            }
            var fallback = new Material(Shader.Find("Sprites/Default"));
            fallback.mainTexture = tex;
            return fallback;
        }

        static Texture2D LoadSprite(string id)
        {
            if (string.IsNullOrEmpty(id)) id = "soft";
            if (SpriteCache.TryGetValue(id, out var cached) && cached != null) return cached;
            var tex = Resources.Load<Texture2D>("CubeCreatorSprites/" + id);
            if (tex == null) tex = SoftDot();
            SpriteCache[id] = tex;
            return tex;
        }

        static Texture2D SoftDot()
        {
            const int S = 64;
            var t = new Texture2D(S, S, TextureFormat.RGBA32, false);
            for (int y = 0; y < S; y++)
                for (int x = 0; x < S; x++)
                {
                    float d = Vector2.Distance(new Vector2(x + 0.5f, y + 0.5f), new Vector2(S / 2f, S / 2f)) / (S / 2f);
                    float a = Mathf.Clamp01(1f - d);
                    t.SetPixel(x, y, new Color(1f, 1f, 1f, a * a));
                }
            t.Apply();
            return t;
        }
    }
}
